module SidebandPriorityQueue_0 ( clock, reset, io_enq_valid, io_enq_bits, 
        io_deq_ready, io_deq_valid, io_deq_bits );
  input [127:0] io_enq_bits;
  output [127:0] io_deq_bits;
  input clock, reset, io_enq_valid, io_deq_ready;
  output io_deq_valid;
  wire   p0_queue_io_deq_valid, p1_queue_io_deq_valid, p2_queue_io_deq_valid,
         enq_arb_io_out_0_valid, enq_arb_io_out_1_valid,
         enq_arb_io_out_2_valid, deq_arb_io_in_0_ready, deq_arb_io_in_1_ready,
         deq_arb_io_in_2_ready;
  wire   [127:0] p0_queue_io_deq_bits;
  wire   [127:0] p1_queue_io_deq_bits;
  wire   [127:0] p2_queue_io_deq_bits;
  wire   [127:0] enq_arb_io_out_0_bits;
  wire   [127:0] enq_arb_io_out_1_bits;
  wire   [127:0] enq_arb_io_out_2_bits;

  Queue_0 p0_queue ( .clock(clock), .reset(reset), .io_enq_valid(
        enq_arb_io_out_0_valid), .io_enq_bits(enq_arb_io_out_0_bits), 
        .io_deq_ready(deq_arb_io_in_0_ready), .io_deq_valid(
        p0_queue_io_deq_valid), .io_deq_bits(p0_queue_io_deq_bits) );
  Queue_1_0 p1_queue ( .clock(clock), .reset(reset), .io_enq_valid(
        enq_arb_io_out_1_valid), .io_enq_bits(enq_arb_io_out_1_bits), 
        .io_deq_ready(deq_arb_io_in_1_ready), .io_deq_valid(
        p1_queue_io_deq_valid), .io_deq_bits(p1_queue_io_deq_bits) );
  Queue_1_3 p2_queue ( .clock(clock), .reset(reset), .io_enq_valid(
        enq_arb_io_out_2_valid), .io_enq_bits(enq_arb_io_out_2_bits), 
        .io_deq_ready(deq_arb_io_in_2_ready), .io_deq_valid(
        p2_queue_io_deq_valid), .io_deq_bits(p2_queue_io_deq_bits) );
  SidebandEnqArbiter_0 enq_arb ( .io_out_0_valid(enq_arb_io_out_0_valid), 
        .io_out_0_bits(enq_arb_io_out_0_bits), .io_out_1_valid(
        enq_arb_io_out_1_valid), .io_out_1_bits(enq_arb_io_out_1_bits), 
        .io_out_2_valid(enq_arb_io_out_2_valid), .io_out_2_bits(
        enq_arb_io_out_2_bits), .io_in_valid(io_enq_valid), .io_in_bits(
        io_enq_bits) );
  SidebandDeqArbiter_0 deq_arb ( .io_out_ready(io_deq_ready), .io_out_valid(
        io_deq_valid), .io_out_bits(io_deq_bits), .io_in_0_ready(
        deq_arb_io_in_0_ready), .io_in_0_valid(p0_queue_io_deq_valid), 
        .io_in_0_bits(p0_queue_io_deq_bits), .io_in_1_ready(
        deq_arb_io_in_1_ready), .io_in_1_valid(p1_queue_io_deq_valid), 
        .io_in_1_bits(p1_queue_io_deq_bits), .io_in_2_ready(
        deq_arb_io_in_2_ready), .io_in_2_valid(p2_queue_io_deq_valid), 
        .io_in_2_bits(p2_queue_io_deq_bits) );
endmodule


