module SidebandNode_1 ( clock, reset, io_inner_layer_to_node_ready, 
        io_inner_layer_to_node_valid, io_inner_layer_to_node_bits, 
        io_inner_node_to_layer_ready, io_inner_node_to_layer_valid, 
        io_inner_node_to_layer_bits, io_outer_tx_bits, io_outer_tx_valid, 
        io_outer_tx_credit, io_outer_rx_bits, io_outer_rx_valid, 
        io_outer_rx_credit );
  input [127:0] io_inner_layer_to_node_bits;
  output [127:0] io_inner_node_to_layer_bits;
  output [31:0] io_outer_tx_bits;
  input [31:0] io_outer_rx_bits;
  input clock, reset, io_inner_layer_to_node_valid,
         io_inner_node_to_layer_ready, io_outer_tx_credit, io_outer_rx_valid;
  output io_inner_layer_to_node_ready, io_inner_node_to_layer_valid,
         io_outer_tx_valid, io_outer_rx_credit;
  wire   rx_des_io_out_valid, n1, n5, n6, n7;
  wire   [127:0] rx_des_io_out_bits;

  AND3X1 U4 ( .IN1(io_inner_node_to_layer_ready), .IN2(n7), .IN3(
        io_inner_node_to_layer_valid), .Q(io_outer_rx_credit) );
  NAND3X0 U5 ( .IN1(io_inner_node_to_layer_bits[4]), .IN2(n6), .IN3(n5), .QN(
        n7) );
  SidebandSerializer_1 tx_ser ( .clock(clock), .reset(reset), .io_in_ready(
        io_inner_layer_to_node_ready), .io_in_valid(
        io_inner_layer_to_node_valid), .io_in_bits(io_inner_layer_to_node_bits), .io_out_bits(io_outer_tx_bits), .io_out_valid(io_outer_tx_valid), 
        .io_out_credit(io_outer_tx_credit) );
  SidebandPriorityQueue_1 rx_queue ( .clock(clock), .reset(reset), 
        .io_enq_valid(rx_des_io_out_valid), .io_enq_bits(rx_des_io_out_bits), 
